-- Partie 1 / 9 : met a jour/ajoute 250 articles
-- (lignes 1 a 250 sur 2164).
-- A executer dans l'ordre du numero de fichier, un par un, dans Supabase
-- SQL Editor (New query -> coller -> Run). Si "Success" ne s'affiche pas,
-- s'arreter et signaler l'erreur avant de continuer.

on conflict (article_normalise) do update set
  nom_article = excluded.nom_article,
  categorie = excluded.categorie,
  unite = excluded.unite,
  gamme = excluded.gamme,
  gamme_statistique = excluded.gamme_statistique,
  min_stock = excluded.min_stock,
  max_stock = excluded.max_stock;
